import{_ as t,o,c as a,a2 as s}from"./chunks/framework.BXzK3EA4.js";const h=JSON.parse('{"title":"Excel","description":"","frontmatter":{},"headers":[],"relativePath":"trading-platform/excel.md","filePath":"trading-platform/excel.md"}'),n={name:"trading-platform/excel.md"};function d(r,e,i,c,l,p){return o(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="excel" tabindex="-1">Excel <a class="header-anchor" href="#excel" aria-label="Permalink to &quot;Excel&quot;">​</a></h1><h2 id="tradeboard-excel-add-in" tabindex="-1">Tradeboard Excel Add-In <a class="header-anchor" href="#tradeboard-excel-add-in" aria-label="Permalink to &quot;Tradeboard Excel Add-In&quot;">​</a></h2><h3 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h3><p>Tradeboard is an Excel Add-In that provides seamless integration with the Tradeboard API for algorithmic trading. This add-in allows users to fetch market data, resolve symbols, analyse option chains and Greeks, place and manage orders, retrieve historical data, and stream real-time market data directly from Excel.</p><p>The add-in exposes <strong>82 worksheet functions</strong> covering <strong>55 of the 57 registered Tradeboard v1 REST method/path pairs</strong>, plus the full WebSocket streaming protocol.</p><h3 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li><strong>Account Management</strong>: Funds, order book, trade book, position book, holdings, and pre-trade margin.</li><li><strong>Market Data</strong>: Real-time quotes, multi-symbol quotes, market depth, historical candles, and supported intervals.</li><li><strong>Symbol Services</strong>: Symbol metadata, instrument search, and expiry dates.</li><li><strong>Options Analytics</strong>: Option chain, Black-76 Greeks, batch Greeks, synthetic futures, and option symbol resolution.</li><li><strong>Order Management</strong>: Place, modify, cancel, and query orders; smart, basket, split, and options orders.</li><li><strong>GTT Orders</strong>: Place, modify, cancel, and list Good Till Triggered orders, including OCO.</li><li><strong>Risk Management</strong>: Close all open positions for a strategy, and an explicit trading arm switch.</li><li><strong>Analyzer Mode</strong>: Toggle between sandbox simulation and live trading, with sandbox P&amp;L per symbol.</li><li><strong>Market Calendar</strong>: Holidays, trading session timings, and a holiday check.</li><li><strong>Messaging</strong>: WhatsApp and Telegram notifications.</li><li><strong>WebSocket Streaming</strong>: Real-time LTP, Quote, Depth, and order updates pushed to individual cells via RTD.</li><li><strong>Persistent Configuration</strong>: API key and settings are saved to disk and auto-loaded on Excel restart.</li></ul><hr><h3 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h3><ul><li>.NET 8.0 Desktop Runtime installed</li><li>Excel-DNA Add-In (included in the project dependencies)</li><li>Microsoft Excel (Office 365 recommended)</li><li>A running Tradeboard server</li></ul><h3 id="install-the-tradeboard-excel-add-in" tabindex="-1">Install the Tradeboard Excel Add-In <a class="header-anchor" href="#install-the-tradeboard-excel-add-in" aria-label="Permalink to &quot;Install the Tradeboard Excel Add-In&quot;">​</a></h3><p>Before installing, ensure you are selecting the correct version based on your Excel installation.</p><h4 id="steps-to-check-your-excel-version" tabindex="-1">Steps to Check Your Excel Version <a class="header-anchor" href="#steps-to-check-your-excel-version" aria-label="Permalink to &quot;Steps to Check Your Excel Version&quot;">​</a></h4><ol><li>Open Microsoft Excel</li><li>Click <strong>File</strong> &gt; <strong>Account</strong></li><li>Click <strong>About Excel</strong></li><li>Look for <strong>32-bit</strong> or <strong>64-bit</strong> in the version details.</li></ol><h4 id="which-version-should-you-install" tabindex="-1">Which Version Should You Install? <a class="header-anchor" href="#which-version-should-you-install" aria-label="Permalink to &quot;Which Version Should You Install?&quot;">​</a></h4><ul><li>If your Excel version is <strong>64-bit</strong> &gt; Install the 64-bit add-in (Recommended)</li><li>If your Excel version is <strong>32-bit</strong> &gt; Install the 32-bit add-in</li></ul><p>The installer detects your Excel bitness automatically and installs the matching add-in.</p><p><strong>Download the Tradeboard Excel Add-In</strong>: <a href="https://github.com/marketcalls/Tradeboard-Excel/releases" target="_blank" rel="noreferrer">GitHub Releases</a></p><h4 id="net-8-desktop-runtime-is-required" tabindex="-1">.NET 8 Desktop Runtime is Required <a class="header-anchor" href="#net-8-desktop-runtime-is-required" aria-label="Permalink to &quot;.NET 8 Desktop Runtime is Required&quot;">​</a></h4><p>Tradeboard Excel Add-In is built using <strong>Excel-DNA</strong>, which requires the <strong>.NET 8 Desktop Runtime</strong> to run.</p><p>If the add-in is not working or Excel does not recognize it, install the .NET 8 Desktop Runtime from: <a href="https://dotnet.microsoft.com/en-us/download/dotnet/8.0" target="_blank" rel="noreferrer">Download .NET 8 Desktop Runtime</a></p><p>After installing the runtime, restart your system and try loading the add-in again.</p><hr><h3 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h3><h4 id="setting-api-key-version-and-host-url" tabindex="-1">Setting API Key, Version, and Host URL <a class="header-anchor" href="#setting-api-key-version-and-host-url" aria-label="Permalink to &quot;Setting API Key, Version, and Host URL&quot;">​</a></h4><p><strong>Function:</strong> <code>oa_api(APIKey, [APIVersion], [HostURL])</code></p><p>This function must be called once to configure the API connection. The configuration is <strong>persisted to disk</strong> at <code>%LOCALAPPDATA%\\Tradeboard\\config.json</code>, so you only need to call it once. On subsequent Excel sessions, the saved API key is automatically loaded.</p><p>All other functions use these stored credentials.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>api_key</code></td><td>Yes</td><td>-</td><td>API key for authentication</td></tr><tr><td><code>version</code></td><td>No</td><td><code>&quot;v1&quot;</code></td><td>API version</td></tr><tr><td><code>HostURL</code></td><td>No</td><td><code>&quot;http://127.0.0.1:5000&quot;</code></td><td>Tradeboard server URL</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_api(&quot;your_api_key&quot;)</span></span>
<span class="line"><span>=oa_api(&quot;your_api_key&quot;, &quot;v1&quot;, &quot;http://127.0.0.1:5000&quot;)</span></span></code></pre></div><hr><h4 id="check-the-add-in-version-and-configuration" tabindex="-1">Check the Add-In Version and Configuration <a class="header-anchor" href="#check-the-add-in-version-and-configuration" aria-label="Permalink to &quot;Check the Add-In Version and Configuration&quot;">​</a></h4><p><strong>Function:</strong> <code>oa_version()</code></p><p>Returns the add-in version and the configuration in force: host URL, API version, REST base, WebSocket URL, timeouts, and whether an API key is set. Makes no network call, so quote this first when reporting a problem.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_version()</span></span></code></pre></div><hr><h4 id="verify-the-connection" tabindex="-1">Verify the Connection <a class="header-anchor" href="#verify-the-connection" aria-label="Permalink to &quot;Verify the Connection&quot;">​</a></h4><p><strong>Function:</strong> <code>oa_ping()</code></p><p>Verifies the API key resolves to an active broker session and names the broker. This is an authenticated check, not a process health probe: a revoked key or a logged-out broker fails it.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_ping()</span></span></code></pre></div><hr><h4 id="trading-safety-switch-optional" tabindex="-1">Trading Safety Switch (optional) <a class="header-anchor" href="#trading-safety-switch-optional" aria-label="Permalink to &quot;Trading Safety Switch (optional)&quot;">​</a></h4><p><strong>Function:</strong> <code>oa_trading_enabled([Enable])</code></p><p>Order functions work out of the box, so nothing needs to be enabled before placing an order. This switch is an <strong>optional</strong> guard you can turn on if you want it.</p><p>A worksheet formula re-evaluates whenever the sheet recalculates, so an order formula sitting in a cell can fire again on a full rebuild (Ctrl+Alt+F9). Setting the switch to FALSE makes every order function refuse to send until you set it back.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_trading_enabled()        Read the current state</span></span>
<span class="line"><span>=oa_trading_enabled(FALSE)   Block order functions from sending</span></span>
<span class="line"><span>=oa_trading_enabled(TRUE)    Allow them again (the default)</span></span></code></pre></div><p>The setting lives for the current Excel session only and is not saved.</p><p>Functions it controls: <code>oa_placeorder</code>, <code>oa_placesmartorder</code>, <code>oa_basketorder</code>, <code>oa_splitorder</code>, <code>oa_modifyorder</code>, <code>oa_cancelorder</code>, <code>oa_cancelallorder</code>, <code>oa_closeposition</code>, <code>oa_placegttorder</code>, <code>oa_modifygttorder</code>, <code>oa_cancelgttorder</code>, <code>oa_optionsorder</code>, <code>oa_optionsmultiorder</code>.</p><hr><h4 id="generic-endpoint-access" tabindex="-1">Generic Endpoint Access <a class="header-anchor" href="#generic-endpoint-access" aria-label="Permalink to &quot;Generic Endpoint Access&quot;">​</a></h4><p><strong>Function:</strong> <code>oa_request(Method, Path, [JSONBody])</code></p><p>Raw call to any Tradeboard endpoint, returning the JSON response in a single cell. The API key is added for you: do not put <code>apikey</code> in the body.</p><p><strong>Function:</strong> <code>oa_json(JSONText, Path)</code></p><p>Pulls a value out of JSON text with a JSONPath expression. Objects and arrays come back as compact JSON, scalars as numbers, booleans, or text.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_request(&quot;POST&quot;, &quot;ping&quot;)</span></span>
<span class="line"><span>=oa_json(A1, &quot;data.broker&quot;)</span></span>
<span class="line"><span>=oa_json(A1, &quot;data[0].symbol&quot;)</span></span></code></pre></div><p>Use these to reach any endpoint the add-in does not wrap directly, such as <code>POST /telegram/webhook</code>.</p><hr><h3 id="account-functions" tabindex="-1">Account Functions <a class="header-anchor" href="#account-functions" aria-label="Permalink to &quot;Account Functions&quot;">​</a></h3><h4 id="retrieve-funds" tabindex="-1">Retrieve Funds <a class="header-anchor" href="#retrieve-funds" aria-label="Permalink to &quot;Retrieve Funds&quot;">​</a></h4><p><strong>Function:</strong> <code>oa_funds()</code></p><p>Account funds: available cash, collateral, realised and unrealised M2M, and utilised margin. Returns a two-column table.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_funds()</span></span></code></pre></div><hr><h4 id="retrieve-order-book" tabindex="-1">Retrieve Order Book <a class="header-anchor" href="#retrieve-order-book" aria-label="Permalink to &quot;Retrieve Order Book&quot;">​</a></h4><p><strong>Function:</strong> <code>oa_orderbook()</code></p><p>All orders placed today, one row per order: order id, symbol, exchange, action, quantity, price, trigger price, price type, product, status, and timestamp.</p><p><strong>Function:</strong> <code>oa_orderbook_stats()</code></p><p>Order book summary counts: buy, sell, completed, open, and rejected orders.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_orderbook()</span></span>
<span class="line"><span>=oa_orderbook_stats()</span></span></code></pre></div><hr><h4 id="retrieve-trade-book" tabindex="-1">Retrieve Trade Book <a class="header-anchor" href="#retrieve-trade-book" aria-label="Permalink to &quot;Retrieve Trade Book&quot;">​</a></h4><p><strong>Function:</strong> <code>oa_tradebook()</code></p><p>Executed trades for today, one row per fill: order id, symbol, exchange, action, quantity, average price, product, timestamp, and trade value.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_tradebook()</span></span></code></pre></div><hr><h4 id="retrieve-position-book" tabindex="-1">Retrieve Position Book <a class="header-anchor" href="#retrieve-position-book" aria-label="Permalink to &quot;Retrieve Position Book&quot;">​</a></h4><p><strong>Function:</strong> <code>oa_positionbook()</code></p><p>Open and closed positions for today with live P&amp;L: symbol, exchange, product, quantity, average price, LTP, and PnL. A quantity of 0 means the position was closed and the row carries the realised P&amp;L.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_positionbook()</span></span></code></pre></div><hr><h4 id="retrieve-holdings" tabindex="-1">Retrieve Holdings <a class="header-anchor" href="#retrieve-holdings" aria-label="Permalink to &quot;Retrieve Holdings&quot;">​</a></h4><p><strong>Function:</strong> <code>oa_holdings()</code></p><p>Delivery holdings with P&amp;L: symbol, exchange, product, quantity, PnL, and PnL percent.</p><p><strong>Function:</strong> <code>oa_holdings_stats()</code></p><p>Portfolio totals: current market value, invested value, total P&amp;L, and total P&amp;L percentage.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_holdings()</span></span>
<span class="line"><span>=oa_holdings_stats()</span></span></code></pre></div><hr><h4 id="calculate-pre-trade-margin" tabindex="-1">Calculate Pre-Trade Margin <a class="header-anchor" href="#calculate-pre-trade-margin" aria-label="Permalink to &quot;Calculate Pre-Trade Margin&quot;">​</a></h4><p><strong>Function:</strong> <code>oa_margin(Positions, [Exchange], [Product], [PriceType])</code></p><p>Pre-trade margin for a basket of up to 50 positions, including hedging benefit. Reads the basket from a range and returns total margin required, SPAN, exposure, and margin benefit.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>Positions</code></td><td>Yes</td><td>Range of positions. With a header row, columns are matched by name</td></tr><tr><td><code>Exchange</code></td><td>No</td><td>Default exchange applied to rows that do not specify one</td></tr><tr><td><code>Product</code></td><td>No</td><td>Default product</td></tr><tr><td><code>PriceType</code></td><td>No</td><td>Default price type</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_margin(A2:E5)</span></span>
<span class="line"><span>=oa_margin(A2:E5, &quot;NFO&quot;, &quot;NRML&quot;)</span></span></code></pre></div><hr><h3 id="market-data-functions" tabindex="-1">Market Data Functions <a class="header-anchor" href="#market-data-functions" aria-label="Permalink to &quot;Market Data Functions&quot;">​</a></h3><h4 id="get-last-traded-price" tabindex="-1">Get Last Traded Price <a class="header-anchor" href="#get-last-traded-price" aria-label="Permalink to &quot;Get Last Traded Price&quot;">​</a></h4><p><strong>Function:</strong> <code>oa_ltp(Symbol, Exchange)</code></p><p>Last traded price as a single number. This is the most convenient function for building a watchlist column.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_ltp(&quot;RELIANCE&quot;, &quot;NSE&quot;)</span></span></code></pre></div><hr><h4 id="get-a-single-quote-field" tabindex="-1">Get a Single Quote Field <a class="header-anchor" href="#get-a-single-quote-field" aria-label="Permalink to &quot;Get a Single Quote Field&quot;">​</a></h4><p><strong>Function:</strong> <code>oa_field(Symbol, Exchange, Field)</code></p><p>One named field of a market quote as a single value. Parallels the streaming <code>oa_ws_field</code>.</p><p>Supported fields: <code>ltp</code>, <code>open</code>, <code>high</code>, <code>low</code>, <code>prev_close</code>, <code>bid</code>, <code>ask</code>, <code>volume</code>, <code>oi</code>, plus the computed <code>change</code> and <code>changepct</code>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_field(&quot;RELIANCE&quot;, &quot;NSE&quot;, &quot;high&quot;)</span></span>
<span class="line"><span>=oa_field(&quot;RELIANCE&quot;, &quot;NSE&quot;, &quot;changepct&quot;)</span></span></code></pre></div><hr><h4 id="get-market-quotes" tabindex="-1">Get Market Quotes <a class="header-anchor" href="#get-market-quotes" aria-label="Permalink to &quot;Get Market Quotes&quot;">​</a></h4><p><strong>Function:</strong> <code>oa_quotes(Symbol, Exchange)</code></p><p>Full market quote for a symbol as a key/value table, including computed Change and Change %.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_quotes(&quot;RELIANCE&quot;, &quot;NSE&quot;)</span></span></code></pre></div><hr><h4 id="get-quotes-for-multiple-symbols" tabindex="-1">Get Quotes for Multiple Symbols <a class="header-anchor" href="#get-quotes-for-multiple-symbols" aria-label="Permalink to &quot;Get Quotes for Multiple Symbols&quot;">​</a></h4><p><strong>Function:</strong> <code>oa_multiquotes(Symbols, DefaultExchange)</code></p><p>Quotes for a range of symbols, one row per symbol. Far more efficient than one <code>oa_quotes</code> call per symbol.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>Symbols</code></td><td>Yes</td><td>Range: one column of symbols, or two columns of symbol and exchange</td></tr><tr><td><code>DefaultExchange</code></td><td>No</td><td>Exchange applied when the range has no exchange column (default <code>NSE</code>)</td></tr></tbody></table><p>Returns Symbol, Exchange, LTP, Open, High, Low, Prev Close, Change, Change %, Bid, Ask, OI, Volume, and an Error column for symbols the server could not resolve.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_multiquotes(A2:A20)</span></span>
<span class="line"><span>=oa_multiquotes(A2:B20)</span></span>
<span class="line"><span>=oa_multiquotes(A2:A20, &quot;NSE&quot;)</span></span></code></pre></div><hr><h4 id="get-market-depth" tabindex="-1">Get Market Depth <a class="header-anchor" href="#get-market-depth" aria-label="Permalink to &quot;Get Market Depth&quot;">​</a></h4><p><strong>Function:</strong> <code>oa_depth(Symbol, Exchange)</code></p><p>Order book depth with the day summary. Returns the five-level bid and ask ladder plus LTP, Volume, Open, High, Low, Prev Close, LTQ, OI, Total Buy Qty, and Total Sell Qty.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_depth(&quot;RELIANCE&quot;, &quot;NSE&quot;)</span></span></code></pre></div><hr><h4 id="fetch-historical-data" tabindex="-1">Fetch Historical Data <a class="header-anchor" href="#fetch-historical-data" aria-label="Permalink to &quot;Fetch Historical Data&quot;">​</a></h4><p><strong>Function:</strong> <code>oa_history(Symbol, Exchange, Interval, StartDate, EndDate, [Source])</code></p><table tabindex="0"><thead><tr><th>Parameter</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>Symbol</code></td><td>Yes</td><td>Trading symbol</td></tr><tr><td><code>Exchange</code></td><td>Yes</td><td>Exchange</td></tr><tr><td><code>Interval</code></td><td>Yes</td><td>Candle interval, for example <code>&quot;1m&quot;</code>, <code>&quot;5m&quot;</code>, <code>&quot;15m&quot;</code>, <code>&quot;D&quot;</code></td></tr><tr><td><code>StartDate</code></td><td>Yes</td><td>Start date, <code>YYYY-MM-DD</code> or a real Excel date cell</td></tr><tr><td><code>EndDate</code></td><td>Yes</td><td>End date, <code>YYYY-MM-DD</code> or a real Excel date cell</td></tr><tr><td><code>Source</code></td><td>No</td><td><code>&quot;api&quot;</code> for the broker (default) or <code>&quot;db&quot;</code> for Historify stored data</td></tr></tbody></table><p>Returns a table with Ticker, Date (a real Excel date serial), Time (IST), Open, High, Low, Close, Volume, and OI when the payload carries it.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_history(&quot;RELIANCE&quot;, &quot;NSE&quot;, &quot;5m&quot;, &quot;2026-04-01&quot;, &quot;2026-04-08&quot;)</span></span>
<span class="line"><span>=oa_history(&quot;RELIANCE&quot;, &quot;NSE&quot;, &quot;D&quot;, &quot;2025-01-01&quot;, &quot;2026-01-01&quot;, &quot;db&quot;)</span></span></code></pre></div><hr><h4 id="get-supported-intervals" tabindex="-1">Get Supported Intervals <a class="header-anchor" href="#get-supported-intervals" aria-label="Permalink to &quot;Get Supported Intervals&quot;">​</a></h4><p><strong>Function:</strong> <code>oa_intervals()</code></p><p>Candle intervals supported by the connected broker, grouped by category.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_intervals()</span></span></code></pre></div><hr><h3 id="symbol-functions" tabindex="-1">Symbol Functions <a class="header-anchor" href="#symbol-functions" aria-label="Permalink to &quot;Symbol Functions&quot;">​</a></h3><h4 id="get-symbol-metadata" tabindex="-1">Get Symbol Metadata <a class="header-anchor" href="#get-symbol-metadata" aria-label="Permalink to &quot;Get Symbol Metadata&quot;">​</a></h4><p><strong>Function:</strong> <code>oa_symbol(Symbol, Exchange)</code></p><p>Instrument metadata: name, broker symbol, instrument type, expiry, strike, lot size, tick size, freeze quantity, and token.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_symbol(&quot;RELIANCE&quot;, &quot;NSE&quot;)</span></span></code></pre></div><hr><h4 id="get-lot-size-and-token" tabindex="-1">Get Lot Size and Token <a class="header-anchor" href="#get-lot-size-and-token" aria-label="Permalink to &quot;Get Lot Size and Token&quot;">​</a></h4><p><strong>Function:</strong> <code>oa_lotsize(Symbol, Exchange)</code> returns the lot size as a single number, which is what you need when sizing an F&amp;O order from a sheet.</p><p><strong>Function:</strong> <code>oa_token(Symbol, Exchange)</code> returns the broker instrument token as text.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_lotsize(&quot;NIFTY25AUG26FUT&quot;, &quot;NFO&quot;)</span></span>
<span class="line"><span>=oa_token(&quot;RELIANCE&quot;, &quot;NSE&quot;)</span></span></code></pre></div><hr><h4 id="search-instruments" tabindex="-1">Search Instruments <a class="header-anchor" href="#search-instruments" aria-label="Permalink to &quot;Search Instruments&quot;">​</a></h4><p><strong>Function:</strong> <code>oa_search(Query, [Exchange])</code></p><p>Searches instruments by name, strike, month, or option type. The tradable symbol is the first column so another formula can reference it directly.</p><p>Returns Symbol, Name, Exchange, Instrument Type, Expiry, Strike, Lot Size, Tick Size, Freeze Qty, Broker Symbol, Broker Exchange, and Token.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_search(&quot;NIFTY 25000 CE&quot;)</span></span>
<span class="line"><span>=oa_search(&quot;RELIANCE&quot;, &quot;NSE&quot;)</span></span></code></pre></div><p>This is the fastest way to find the correct Tradeboard symbol format for an F&amp;O contract.</p><hr><h4 id="get-expiry-dates" tabindex="-1">Get Expiry Dates <a class="header-anchor" href="#get-expiry-dates" aria-label="Permalink to &quot;Get Expiry Dates&quot;">​</a></h4><p><strong>Function:</strong> <code>oa_expiry(Symbol, Exchange, InstrumentType, [ExpiryType])</code></p><table tabindex="0"><thead><tr><th>Parameter</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>Symbol</code></td><td>Yes</td><td>Underlying symbol, for example <code>NIFTY</code></td></tr><tr><td><code>Exchange</code></td><td>Yes</td><td>F&amp;O exchange: <code>NFO</code>, <code>BFO</code>, <code>MCX</code>, <code>CDS</code>, <code>CRYPTO</code></td></tr><tr><td><code>InstrumentType</code></td><td>Yes</td><td><code>&quot;futures&quot;</code> or <code>&quot;options&quot;</code></td></tr><tr><td><code>ExpiryType</code></td><td>No</td><td><code>&quot;monthly&quot;</code>, <code>&quot;weekly&quot;</code>, or <code>&quot;all&quot;</code>. Applied locally, see note below</td></tr></tbody></table><p>Returns Expiry (in the <code>DD-MMM-YY</code> form the API expects back), Date (an Excel serial), and Type.</p><blockquote><p><strong>Note:</strong> <code>expirytype</code> is not a parameter the Tradeboard server accepts. <code>ExpirySchema</code> declares only <code>apikey</code>, <code>symbol</code>, <code>exchange</code>, and <code>instrumenttype</code>, and rejects unknown fields, so sending it returns HTTP 400. This add-in applies the filter locally after fetching the full list.</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_expiry(&quot;NIFTY&quot;, &quot;NFO&quot;, &quot;options&quot;)</span></span>
<span class="line"><span>=oa_expiry(&quot;NIFTY&quot;, &quot;NFO&quot;, &quot;options&quot;, &quot;monthly&quot;)</span></span></code></pre></div><hr><h3 id="options-functions" tabindex="-1">Options Functions <a class="header-anchor" href="#options-functions" aria-label="Permalink to &quot;Options Functions&quot;">​</a></h3><h4 id="option-chain" tabindex="-1">Option Chain <a class="header-anchor" href="#option-chain" aria-label="Permalink to &quot;Option Chain&quot;">​</a></h4><p><strong>Function:</strong> <code>oa_optionchain(Underlying, Exchange, Expiry, [StrikeCount], [WithGreeks], [InterestRate])</code></p><table tabindex="0"><thead><tr><th>Parameter</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>Underlying</code></td><td>Yes</td><td>Underlying symbol, for example <code>NIFTY</code>, <code>BANKNIFTY</code>, <code>SENSEX</code></td></tr><tr><td><code>Exchange</code></td><td>Yes</td><td>Underlying exchange: <code>NSE_INDEX</code> or <code>BSE_INDEX</code></td></tr><tr><td><code>Expiry</code></td><td>Yes</td><td>Expiry in <code>DDMMMYY</code> format, for example <code>25AUG26</code></td></tr><tr><td><code>StrikeCount</code></td><td>No</td><td>Strikes above and below ATM, 1 to 100. Default is all strikes</td></tr><tr><td><code>WithGreeks</code></td><td>No</td><td>TRUE to attach IV and Greeks to every leg. Default TRUE, costs no extra call</td></tr><tr><td><code>InterestRate</code></td><td>No</td><td>Risk-free rate as an annualised percent, Greeks only. Default 0</td></tr></tbody></table><p><strong>Layout:</strong> row 1 carries the context (Underlying, Spot, Prev Close, ATM Strike, Expiry, Forward, Strike count). Row 2 carries column headers. From row 3, one row per strike, laid out <strong>calls on the left, strike in the centre, puts on the right</strong>, mirrored around the strike so the ladder reads outward from the money.</p><p>Per side: LTP, Bid, Bid Qty, Ask, Ask Qty, IV, Delta, Gamma, Theta, Vega, Volume, OI, Open, High, Low, Prev Close, Lot Size, Tick Size, Symbol. Width is 41 columns with Greeks, 31 without.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_optionchain(&quot;NIFTY&quot;, &quot;NSE_INDEX&quot;, &quot;25AUG26&quot;)</span></span>
<span class="line"><span>=oa_optionchain(&quot;NIFTY&quot;, &quot;NSE_INDEX&quot;, &quot;25AUG26&quot;, 10)</span></span>
<span class="line"><span>=oa_optionchain(&quot;BANKNIFTY&quot;, &quot;NSE_INDEX&quot;, &quot;25AUG26&quot;, 15, FALSE)</span></span></code></pre></div><hr><h4 id="option-greeks" tabindex="-1">Option Greeks <a class="header-anchor" href="#option-greeks" aria-label="Permalink to &quot;Option Greeks&quot;">​</a></h4><p><strong>Function:</strong> <code>oa_optiongreeks(Symbol, Exchange, [InterestRate], [ExpiryTime], [UnderlyingSymbol], [UnderlyingExchange], [ForwardPrice])</code></p><p>Black-76 Greeks and implied volatility for one option. Returns IV plus delta, gamma, theta, vega, and rho.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_optiongreeks(&quot;NIFTY25AUG2625000CE&quot;, &quot;NFO&quot;)</span></span>
<span class="line"><span>=oa_optiongreeks(&quot;NIFTY25AUG2625000CE&quot;, &quot;NFO&quot;, 7.0, &quot;15:30&quot;)</span></span></code></pre></div><hr><h4 id="batch-option-greeks" tabindex="-1">Batch Option Greeks <a class="header-anchor" href="#batch-option-greeks" aria-label="Permalink to &quot;Batch Option Greeks&quot;">​</a></h4><p><strong>Function:</strong> <code>oa_multioptiongreeks(Symbols, [InterestRate], [ExpiryTime])</code></p><p>Greeks and IV for up to 50 options in one call.</p><p>The range accepts one column (symbols, exchange defaults to <code>NFO</code>), two columns (symbol, exchange), or four columns adding per-item <code>underlying_symbol</code> and <code>underlying_exchange</code> overrides.</p><p>Row 1 is the batch summary (Total, Success, Failed). Then one row per contract: Symbol, Exchange, Status, IV, Delta, Gamma, Theta, Vega, Rho, Error.</p><blockquote><p>Individual items can fail while the batch still reports success, so check the Status and Error columns per row.</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_multioptiongreeks(A2:A20)</span></span>
<span class="line"><span>=oa_multioptiongreeks(A2:B20, 7.0)</span></span></code></pre></div><hr><h4 id="resolve-an-option-symbol" tabindex="-1">Resolve an Option Symbol <a class="header-anchor" href="#resolve-an-option-symbol" aria-label="Permalink to &quot;Resolve an Option Symbol&quot;">​</a></h4><p><strong>Function:</strong> <code>oa_optionsymbol(Underlying, Exchange, Expiry, StrikeOffset, OptionType)</code></p><p>Resolves an option trading symbol from underlying, expiry, and strike offset. <code>strike_offset</code> is <code>ATM</code>, <code>ITM1</code> to <code>ITM50</code>, or <code>OTM1</code> to <code>OTM50</code>. <code>option_type</code> is <code>CE</code> or <code>PE</code>.</p><p>The resolved symbol is the first data row, so <code>INDEX(range, 2, 2)</code> feeds it into another formula.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_optionsymbol(&quot;NIFTY&quot;, &quot;NSE_INDEX&quot;, &quot;25AUG26&quot;, &quot;ATM&quot;, &quot;CE&quot;)</span></span>
<span class="line"><span>=oa_optionsymbol(&quot;NIFTY&quot;, &quot;NSE_INDEX&quot;, &quot;25AUG26&quot;, &quot;OTM2&quot;, &quot;PE&quot;)</span></span></code></pre></div><hr><h4 id="synthetic-future" tabindex="-1">Synthetic Future <a class="header-anchor" href="#synthetic-future" aria-label="Permalink to &quot;Synthetic Future&quot;">​</a></h4><p><strong>Function:</strong> <code>oa_syntheticfuture(Underlying, Exchange, Expiry)</code></p><p>Synthetic futures price for an expiry, derived from ATM options using put-call parity. Also reports the Basis (synthetic minus spot).</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_syntheticfuture(&quot;NIFTY&quot;, &quot;NSE_INDEX&quot;, &quot;25AUG26&quot;)</span></span></code></pre></div><hr><h4 id="place-an-option-order" tabindex="-1">Place an Option Order <a class="header-anchor" href="#place-an-option-order" aria-label="Permalink to &quot;Place an Option Order&quot;">​</a></h4><p><strong>Function:</strong> <code>oa_optionsorder(Strategy, Underlying, Exchange, Expiry, StrikeOffset, OptionType, Action, Quantity, [PriceType], [Product], [Price], [TriggerPrice], [SplitSize])</code></p><p>Places an option order by strike offset rather than by resolved symbol.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>Strategy</code></td><td>Yes</td><td>-</td><td>Strategy identifier recorded against the order</td></tr><tr><td><code>Underlying</code></td><td>Yes</td><td>-</td><td>Underlying symbol</td></tr><tr><td><code>Exchange</code></td><td>Yes</td><td>-</td><td><code>NSE_INDEX</code>, <code>BSE_INDEX</code>, <code>NFO</code>, or <code>BFO</code></td></tr><tr><td><code>Expiry</code></td><td>Yes</td><td>-</td><td>Expiry in <code>DDMMMYY</code> format</td></tr><tr><td><code>StrikeOffset</code></td><td>Yes</td><td>-</td><td><code>ATM</code>, <code>ITM1</code> to <code>ITM50</code>, <code>OTM1</code> to <code>OTM50</code></td></tr><tr><td><code>OptionType</code></td><td>Yes</td><td>-</td><td><code>CE</code> or <code>PE</code></td></tr><tr><td><code>Action</code></td><td>Yes</td><td>-</td><td><code>BUY</code> or <code>SELL</code></td></tr><tr><td><code>Quantity</code></td><td>Yes</td><td>-</td><td>Quantity in units, not lots</td></tr><tr><td><code>PriceType</code></td><td>No</td><td><code>MARKET</code></td><td><code>MARKET</code>, <code>LIMIT</code>, <code>SL</code>, <code>SL-M</code></td></tr><tr><td><code>Product</code></td><td>No</td><td><code>MIS</code></td><td><code>MIS</code> or <code>NRML</code></td></tr><tr><td><code>Price</code></td><td>No</td><td>0</td><td>Limit price for <code>LIMIT</code> and <code>SL</code></td></tr><tr><td><code>TriggerPrice</code></td><td>No</td><td>0</td><td>Trigger price for <code>SL</code> and <code>SL-M</code></td></tr><tr><td><code>SplitSize</code></td><td>No</td><td>0</td><td>Split into chunks of this size, 0 for no split</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_optionsorder(&quot;MyStrategy&quot;, &quot;NIFTY&quot;, &quot;NSE_INDEX&quot;, &quot;25AUG26&quot;, &quot;ATM&quot;, &quot;CE&quot;, &quot;BUY&quot;, 75)</span></span></code></pre></div><hr><h4 id="place-a-multi-leg-option-strategy" tabindex="-1">Place a Multi-Leg Option Strategy <a class="header-anchor" href="#place-a-multi-leg-option-strategy" aria-label="Permalink to &quot;Place a Multi-Leg Option Strategy&quot;">​</a></h4><p><strong>Function:</strong> <code>oa_optionsmultiorder(Strategy, Underlying, Exchange, Expiry, Legs)</code></p><p>Places a multi-leg option strategy from a table of legs (1 to 20).</p><p>The <code>legs</code> range needs a header row. Recognised columns: <code>Offset</code>, <code>Option Type</code>, <code>Action</code>, <code>Quantity</code> (required), and optionally <code>Expiry</code>, <code>PriceType</code>, <code>Product</code>, <code>SplitSize</code>, <code>Price</code>, <code>TriggerPrice</code>. Annotation columns such as <code>Leg</code>, <code>Notes</code>, and <code>Remarks</code> are ignored.</p><p>Returns one row per leg with its own Symbol, Order ID, Status, and Message, so a failed leg inside an otherwise successful strategy is visible.</p><p>Example sheet layout for a short strangle:</p><table tabindex="0"><thead><tr><th>Offset</th><th>Option Type</th><th>Action</th><th>Quantity</th></tr></thead><tbody><tr><td>OTM3</td><td>CE</td><td>SELL</td><td>75</td></tr><tr><td>OTM3</td><td>PE</td><td>SELL</td><td>75</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_optionsmultiorder(&quot;Strangle&quot;, &quot;NIFTY&quot;, &quot;NSE_INDEX&quot;, &quot;25AUG26&quot;, A1:D3)</span></span></code></pre></div><hr><h3 id="order-functions" tabindex="-1">Order Functions <a class="header-anchor" href="#order-functions" aria-label="Permalink to &quot;Order Functions&quot;">​</a></h3><h4 id="place-an-order" tabindex="-1">Place an Order <a class="header-anchor" href="#place-an-order" aria-label="Permalink to &quot;Place an Order&quot;">​</a></h4><p><strong>Function:</strong> <code>oa_placeorder(Strategy, Symbol, Action, Exchange, PriceType, Product, [Quantity], [Price], [TriggerPrice], [DisclosedQuantity])</code></p><table tabindex="0"><thead><tr><th>Parameter</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>Strategy</code></td><td>Yes</td><td>Trading strategy name</td></tr><tr><td><code>Symbol</code></td><td>Yes</td><td>Trading symbol</td></tr><tr><td><code>Action</code></td><td>Yes</td><td><code>BUY</code> or <code>SELL</code></td></tr><tr><td><code>Exchange</code></td><td>Yes</td><td>Exchange code</td></tr><tr><td><code>PriceType</code></td><td>Yes</td><td><code>MARKET</code>, <code>LIMIT</code>, <code>SL</code>, <code>SL-M</code></td></tr><tr><td><code>Product</code></td><td>Yes</td><td><code>MIS</code>, <code>CNC</code>, <code>NRML</code></td></tr><tr><td><code>Quantity</code></td><td>No</td><td>Order quantity</td></tr><tr><td><code>Price</code></td><td>No</td><td>Limit price</td></tr><tr><td><code>TriggerPrice</code></td><td>No</td><td>Trigger price</td></tr><tr><td><code>DisclosedQuantity</code></td><td>No</td><td>Disclosed quantity</td></tr></tbody></table><p>Returns a Status / Order ID / Message table.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_placeorder(&quot;MyStrategy&quot;, &quot;RELIANCE&quot;, &quot;BUY&quot;, &quot;NSE&quot;, &quot;MARKET&quot;, &quot;MIS&quot;, 10)</span></span></code></pre></div><hr><h4 id="place-a-smart-order" tabindex="-1">Place a Smart Order <a class="header-anchor" href="#place-a-smart-order" aria-label="Permalink to &quot;Place a Smart Order&quot;">​</a></h4><p><strong>Function:</strong> <code>oa_placesmartorder(Strategy, Symbol, Action, Exchange, PriceType, Product, [Quantity], [PositionSize], [Price], [TriggerPrice], [DisclosedQuantity])</code></p><p>Places an order that targets a desired net position size rather than a raw quantity.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_placesmartorder(&quot;MyStrategy&quot;, &quot;RELIANCE&quot;, &quot;BUY&quot;, &quot;NSE&quot;, &quot;MARKET&quot;, &quot;MIS&quot;, 10, 50)</span></span></code></pre></div><hr><h4 id="place-a-basket-order" tabindex="-1">Place a Basket Order <a class="header-anchor" href="#place-a-basket-order" aria-label="Permalink to &quot;Place a Basket Order&quot;">​</a></h4><p><strong>Function:</strong> <code>oa_basketorder(Strategy, Orders)</code></p><p>Places several orders in one call from a range. A header row is detected and skipped.</p><p>Column order: Symbol, Exchange, Action, Quantity, and optionally PriceType, Product, Price, TriggerPrice, DisclosedQuantity.</p><p>Returns one row per leg: Symbol, Status, Order ID, Message.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_basketorder(&quot;MyStrategy&quot;, A2:D5)</span></span></code></pre></div><hr><h4 id="place-a-split-order" tabindex="-1">Place a Split Order <a class="header-anchor" href="#place-a-split-order" aria-label="Permalink to &quot;Place a Split Order&quot;">​</a></h4><p><strong>Function:</strong> <code>oa_splitorder(Strategy, Symbol, Action, Exchange, [Quantity], [SplitSize], PriceType, Product, [Price], [TriggerPrice], [DisclosedQuantity])</code></p><p>Splits a large quantity into chunks. Returns one row per child order: Order Num, Order ID, Quantity, Status, Message.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_splitorder(&quot;MyStrategy&quot;, &quot;RELIANCE&quot;, &quot;BUY&quot;, &quot;NSE&quot;, 100, 25, &quot;MARKET&quot;, &quot;MIS&quot;)</span></span></code></pre></div><hr><h4 id="modify-an-order" tabindex="-1">Modify an Order <a class="header-anchor" href="#modify-an-order" aria-label="Permalink to &quot;Modify an Order&quot;">​</a></h4><p><strong>Function:</strong> <code>oa_modifyorder(Strategy, OrderID, Symbol, Action, Exchange, [Quantity], PriceType, Product, [Price], [TriggerPrice], [DisclosedQuantity])</code></p><blockquote><p>The server schema marks <code>price</code>, <code>quantity</code>, <code>trigger_price</code>, <code>disclosed_quantity</code>, <code>pricetype</code>, and <code>product</code> as required for a modify, so all of them are sent even when left blank.</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_modifyorder(&quot;MyStrategy&quot;, &quot;250820000012345&quot;, &quot;RELIANCE&quot;, &quot;BUY&quot;, &quot;NSE&quot;, 20, &quot;LIMIT&quot;, &quot;MIS&quot;, 1250)</span></span></code></pre></div><hr><h4 id="cancel-an-order" tabindex="-1">Cancel an Order <a class="header-anchor" href="#cancel-an-order" aria-label="Permalink to &quot;Cancel an Order&quot;">​</a></h4><p><strong>Function:</strong> <code>oa_cancelorder(Strategy, OrderID)</code></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_cancelorder(&quot;MyStrategy&quot;, &quot;250820000012345&quot;)</span></span></code></pre></div><hr><h4 id="cancel-all-orders" tabindex="-1">Cancel All Orders <a class="header-anchor" href="#cancel-all-orders" aria-label="Permalink to &quot;Cancel All Orders&quot;">​</a></h4><p><strong>Function:</strong> <code>oa_cancelallorder(Strategy)</code></p><p>Cancels all open orders for a strategy. Returns Order ID, Result, and Reason rows so failed cancellations are visible.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_cancelallorder(&quot;MyStrategy&quot;)</span></span></code></pre></div><hr><h4 id="close-all-open-positions" tabindex="-1">Close All Open Positions <a class="header-anchor" href="#close-all-open-positions" aria-label="Permalink to &quot;Close All Open Positions&quot;">​</a></h4><p><strong>Function:</strong> <code>oa_closeposition(Strategy)</code></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_closeposition(&quot;MyStrategy&quot;)</span></span></code></pre></div><hr><h4 id="get-order-status" tabindex="-1">Get Order Status <a class="header-anchor" href="#get-order-status" aria-label="Permalink to &quot;Get Order Status&quot;">​</a></h4><p><strong>Function:</strong> <code>oa_orderstatus(Strategy, OrderID)</code></p><p>Returns the full order record as a key/value table.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_orderstatus(&quot;MyStrategy&quot;, &quot;250820000012345&quot;)</span></span></code></pre></div><hr><h4 id="get-open-position" tabindex="-1">Get Open Position <a class="header-anchor" href="#get-open-position" aria-label="Permalink to &quot;Get Open Position&quot;">​</a></h4><p><strong>Function:</strong> <code>oa_openposition(Strategy, Symbol, Exchange, Product)</code></p><p>Returns the net open position quantity as a single number, so it can feed a formula directly.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_openposition(&quot;MyStrategy&quot;, &quot;RELIANCE&quot;, &quot;NSE&quot;, &quot;MIS&quot;)</span></span></code></pre></div><hr><h3 id="gtt-order-functions" tabindex="-1">GTT Order Functions <a class="header-anchor" href="#gtt-order-functions" aria-label="Permalink to &quot;GTT Order Functions&quot;">​</a></h3><p>Good Till Triggered orders rest at the broker until their trigger fires. Both <code>SINGLE</code> and <code>OCO</code> trigger types are supported.</p><h4 id="place-a-gtt-order" tabindex="-1">Place a GTT Order <a class="header-anchor" href="#place-a-gtt-order" aria-label="Permalink to &quot;Place a GTT Order&quot;">​</a></h4><p><strong>Function:</strong> <code>oa_placegttorder(Strategy, Symbol, Exchange, Action, Product, TriggerType, Quantity, [PriceType], [Price], [TriggerPriceSL], [TriggerPriceTG], [StopLoss], [Target])</code></p><table tabindex="0"><thead><tr><th>Trigger type</th><th>Fields to supply</th></tr></thead><tbody><tr><td><code>SINGLE</code></td><td>One of <code>trigger_price_sl</code> or <code>trigger_price_tg</code>, plus <code>price</code> for a LIMIT</td></tr><tr><td><code>OCO</code></td><td>All four: <code>trigger_price_sl</code>, <code>stoploss</code>, <code>trigger_price_tg</code>, <code>target</code></td></tr></tbody></table><p>For <code>OCO</code>, <code>trigger_price_sl</code> must be below <code>trigger_price_tg</code>. Validation happens locally before any network call.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_placegttorder(&quot;MyStrategy&quot;, &quot;RELIANCE&quot;, &quot;NSE&quot;, &quot;SELL&quot;, &quot;CNC&quot;, &quot;SINGLE&quot;, 10, &quot;LIMIT&quot;, 1300, , 1300)</span></span>
<span class="line"><span>=oa_placegttorder(&quot;MyStrategy&quot;, &quot;RELIANCE&quot;, &quot;NSE&quot;, &quot;SELL&quot;, &quot;CNC&quot;, &quot;OCO&quot;, 10, &quot;LIMIT&quot;, , 1150, 1300, 1145, 1305)</span></span></code></pre></div><hr><h4 id="modify-a-gtt-order" tabindex="-1">Modify a GTT Order <a class="header-anchor" href="#modify-a-gtt-order" aria-label="Permalink to &quot;Modify a GTT Order&quot;">​</a></h4><p><strong>Function:</strong> <code>oa_modifygttorder(Strategy, TriggerID, Symbol, Exchange, Action, Product, TriggerType, Quantity, [PriceType], [Price], [TriggerPriceSL], [TriggerPriceTG], [StopLoss], [Target])</code></p><blockquote><p>A modify replaces the whole trigger, so send every field you want to keep.</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_modifygttorder(&quot;MyStrategy&quot;, &quot;12345678&quot;, &quot;RELIANCE&quot;, &quot;NSE&quot;, &quot;SELL&quot;, &quot;CNC&quot;, &quot;SINGLE&quot;, 10, &quot;LIMIT&quot;, 1320, , 1320)</span></span></code></pre></div><hr><h4 id="cancel-a-gtt-order" tabindex="-1">Cancel a GTT Order <a class="header-anchor" href="#cancel-a-gtt-order" aria-label="Permalink to &quot;Cancel a GTT Order&quot;">​</a></h4><p><strong>Function:</strong> <code>oa_cancelgttorder(Strategy, TriggerID)</code></p><p>Cancelling an OCO removes both legs.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_cancelgttorder(&quot;MyStrategy&quot;, &quot;12345678&quot;)</span></span></code></pre></div><hr><h4 id="retrieve-the-gtt-order-book" tabindex="-1">Retrieve the GTT Order Book <a class="header-anchor" href="#retrieve-the-gtt-order-book" aria-label="Permalink to &quot;Retrieve the GTT Order Book&quot;">​</a></h4><p><strong>Function:</strong> <code>oa_gttorderbook()</code></p><p>One row per trigger with its legs flattened into blocks. A book of only SINGLE triggers is 15 columns wide; a book containing an OCO widens to 21 with <code>Leg 1</code> and <code>Leg 2</code> prefixes.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_gttorderbook()</span></span></code></pre></div><hr><h3 id="analyzer-functions" tabindex="-1">Analyzer Functions <a class="header-anchor" href="#analyzer-functions" aria-label="Permalink to &quot;Analyzer Functions&quot;">​</a></h3><p>Analyzer mode simulates orders in a sandbox instead of sending them to the broker. <strong>Check this before arming a strategy.</strong></p><h4 id="get-analyzer-status" tabindex="-1">Get Analyzer Status <a class="header-anchor" href="#get-analyzer-status" aria-label="Permalink to &quot;Get Analyzer Status&quot;">​</a></h4><p><strong>Function:</strong> <code>oa_analyzerstatus()</code></p><p>Reports whether orders are simulated or sent live, and how many orders the analyzer has logged.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_analyzerstatus()</span></span></code></pre></div><hr><h4 id="toggle-analyzer-mode" tabindex="-1">Toggle Analyzer Mode <a class="header-anchor" href="#toggle-analyzer-mode" aria-label="Permalink to &quot;Toggle Analyzer Mode&quot;">​</a></h4><p><strong>Function:</strong> <code>oa_analyzertoggle(Mode)</code></p><p>Accepts TRUE/FALSE or <code>&quot;analyze&quot;</code>/<code>&quot;live&quot;</code>. The returned table states the resulting mode in its first row.</p><blockquote><p><strong>Warning:</strong> switching to live means every order function sends real orders to the broker.</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_analyzertoggle(TRUE)      Sandbox</span></span>
<span class="line"><span>=oa_analyzertoggle(&quot;live&quot;)    Live trading</span></span></code></pre></div><hr><h4 id="sandbox-p-l-by-symbol" tabindex="-1">Sandbox P&amp;L by Symbol <a class="header-anchor" href="#sandbox-p-l-by-symbol" aria-label="Permalink to &quot;Sandbox P&amp;L by Symbol&quot;">​</a></h4><p><strong>Function:</strong> <code>oa_pnl_symbols()</code></p><p>Sandbox P&amp;L per symbol with realised, unrealised, and today totals. Analyzer mode only: in live mode the API answers HTTP 400 and this function says so.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_pnl_symbols()</span></span></code></pre></div><hr><h3 id="market-calendar-functions" tabindex="-1">Market Calendar Functions <a class="header-anchor" href="#market-calendar-functions" aria-label="Permalink to &quot;Market Calendar Functions&quot;">​</a></h3><h4 id="market-holidays" tabindex="-1">Market Holidays <a class="header-anchor" href="#market-holidays" aria-label="Permalink to &quot;Market Holidays&quot;">​</a></h4><p><strong>Function:</strong> <code>oa_holidays([Year], [Exchange])</code></p><p>Market holidays for a year: date, description, holiday type, the exchanges that are closed, and any special sessions. Times shown in IST.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_holidays()</span></span>
<span class="line"><span>=oa_holidays(2026, &quot;NSE&quot;)</span></span></code></pre></div><hr><h4 id="trading-timings" tabindex="-1">Trading Timings <a class="header-anchor" href="#trading-timings" aria-label="Permalink to &quot;Trading Timings&quot;">​</a></h4><p><strong>Function:</strong> <code>oa_timings([Date])</code></p><p>Trading sessions for a date, one row per exchange, with IST start and end times. Defaults to today. An empty schedule means the market is closed that day.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_timings()</span></span>
<span class="line"><span>=oa_timings(&quot;2026-08-15&quot;)</span></span></code></pre></div><hr><h4 id="holiday-check" tabindex="-1">Holiday Check <a class="header-anchor" href="#holiday-check" aria-label="Permalink to &quot;Holiday Check&quot;">​</a></h4><p><strong>Function:</strong> <code>oa_isholiday(Date, [Exchange])</code></p><p>Returns TRUE when the market is closed on the date.</p><blockquote><p>Derived from <code>/market/timings</code>, since Tradeboard has no <code>/checkholiday</code> endpoint: an empty session schedule means a weekend or holiday. With an exchange given, TRUE means that exchange has no session that day, so an MCX evening session on an NSE holiday correctly returns FALSE for MCX and TRUE for NSE.</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_isholiday(&quot;2026-08-15&quot;)</span></span>
<span class="line"><span>=oa_isholiday(TODAY(), &quot;NSE&quot;)</span></span></code></pre></div><hr><h3 id="chart-preferences" tabindex="-1">Chart Preferences <a class="header-anchor" href="#chart-preferences" aria-label="Permalink to &quot;Chart Preferences&quot;">​</a></h3><p><strong>Function:</strong> <code>oa_chart()</code> reads the chart workspace preferences stored for this API key. The first column holds the exact preference key, so it can be fed straight back into <code>oa_chart_set</code>.</p><p><strong>Function:</strong> <code>oa_chart_set(Key, Value)</code> updates one preference. A value that parses as JSON is sent as JSON, anything else as text. Keys are limited to 50 characters.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_chart()</span></span>
<span class="line"><span>=oa_chart_set(&quot;tv_theme&quot;, &quot;dark&quot;)</span></span>
<span class="line"><span>=oa_chart_set(&quot;tv_chart_layout&quot;, &quot;{&quot;&quot;interval&quot;&quot;:&quot;&quot;15m&quot;&quot;}&quot;)</span></span></code></pre></div><hr><h3 id="messaging-functions" tabindex="-1">Messaging Functions <a class="header-anchor" href="#messaging-functions" aria-label="Permalink to &quot;Messaging Functions&quot;">​</a></h3><h4 id="whatsapp" tabindex="-1">WhatsApp <a class="header-anchor" href="#whatsapp" aria-label="Permalink to &quot;WhatsApp&quot;">​</a></h4><p><strong>Function:</strong> <code>oa_whatsapp([Message], [Recipient], [RecipientType], [ImagePath], [DocumentPath], [Caption], [Filename], [WaitForDelivery])</code></p><p>Sends a WhatsApp text, image, or document to yourself, a linked username, one phone number, or up to 5.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>Message</code></td><td>No*</td><td>Text body, max 4096 characters</td></tr><tr><td><code>Recipient</code></td><td>No</td><td>Username, phone number, or a range of up to 5 phone numbers</td></tr><tr><td><code>RecipientType</code></td><td>No</td><td><code>self</code>, <code>username</code>, <code>phone</code>, or <code>phones</code>. Inferred when omitted</td></tr><tr><td><code>ImagePath</code></td><td>No</td><td>Server-local path to an image</td></tr><tr><td><code>DocumentPath</code></td><td>No</td><td>Server-local path to a document</td></tr><tr><td><code>Caption</code></td><td>No</td><td>Caption for the image</td></tr><tr><td><code>Filename</code></td><td>No</td><td>Override the document&#39;s display name</td></tr><tr><td><code>WaitForDelivery</code></td><td>No</td><td>TRUE to block and return a per-recipient delivery report</td></tr></tbody></table><p>* <code>Message</code> is optional only when <code>ImagePath</code> or <code>DocumentPath</code> is supplied.</p><blockquote><p>Exactly one recipient form is required; combining them is not supported. Attachments are read from the <strong>Tradeboard server&#39;s filesystem</strong>, never uploaded from Excel, and must sit inside the directories listed in <code>WHATSAPP_ATTACHMENT_ROOTS</code>. The 5-recipient cap is a terms-of-service guardrail. Limit 30 calls per minute.</p><p><code>POST /whatsapp/notify</code> is the entire public WhatsApp REST surface. Pairing, start/stop, config, users, broadcast, stats, and preferences are admin-only behind the web session cookie and are deliberately not reachable with an API key.</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_whatsapp(&quot;Strategy armed&quot;, , &quot;self&quot;)</span></span>
<span class="line"><span>=oa_whatsapp(&quot;Order filled&quot;, &quot;919876543210&quot;, &quot;phone&quot;)</span></span>
<span class="line"><span>=oa_whatsapp(&quot;EOD chart&quot;, &quot;rajan&quot;, &quot;username&quot;, &quot;/srv/charts/nifty.png&quot;)</span></span></code></pre></div><hr><h4 id="telegram" tabindex="-1">Telegram <a class="header-anchor" href="#telegram" aria-label="Permalink to &quot;Telegram&quot;">​</a></h4><p><strong>Function:</strong> <code>oa_telegram(Username, Message, [WaitForDelivery], [Priority])</code></p><p>Sends a Telegram message to one linked Tradeboard user. Mirrors <code>client.telegram(username=..., message=...)</code> in the Python SDK.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>Username</code></td><td>Yes</td><td>Tradeboard username already linked to a Telegram ID</td></tr><tr><td><code>Message</code></td><td>Yes</td><td>Message text, max 4096 characters</td></tr><tr><td><code>WaitForDelivery</code></td><td>No</td><td>TRUE to attempt delivery immediately instead of queueing</td></tr><tr><td><code>Priority</code></td><td>No</td><td>1 to 10</td></tr></tbody></table><blockquote><p>By default the call returns as soon as the message is <strong>queued</strong>, so success means queued, not delivered. Pass TRUE to <code>WaitForDelivery</code> to attempt it immediately. Limit 30 calls per minute.</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_telegram(&quot;rajan&quot;, &quot;NIFTY crossed 26000&quot;)</span></span>
<span class="line"><span>=oa_telegram(&quot;rajan&quot;, &quot;Position opened&quot;, TRUE)</span></span></code></pre></div><p>The Telegram management endpoints (bot config, start, stop, linked users, broadcast, stats, per-user preferences) are deliberately <strong>not</strong> wrapped, matching the SDK, which exposes only the notification call. Reach them with <code>oa_request</code> when needed:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_request(&quot;GET&quot;, &quot;telegram/stats&quot;)</span></span>
<span class="line"><span>=oa_request(&quot;POST&quot;, &quot;telegram/start&quot;)</span></span></code></pre></div><hr><h3 id="websocket-functions-real-time-streaming" tabindex="-1">WebSocket Functions (Real-Time Streaming) <a class="header-anchor" href="#websocket-functions-real-time-streaming" aria-label="Permalink to &quot;WebSocket Functions (Real-Time Streaming)&quot;">​</a></h3><h4 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h4><p>Each streaming cell registers as its own <strong>RTD topic</strong>. When a tick arrives for that symbol, only the cells watching it update. Nothing is volatile, and the add-in never asks Excel to recalculate, so the rest of your workbook is untouched and Excel stays responsive.</p><p>The data functions <strong>auto-subscribe</strong>: just type the formula and the subscription is created in the background. A cell shows <code>Subscribing...</code> then <code>Waiting for data...</code> before the first tick arrives.</p><h4 id="connection-management" tabindex="-1">Connection Management <a class="header-anchor" href="#connection-management" aria-label="Permalink to &quot;Connection Management&quot;">​</a></h4><h5 id="connect-to-websocket" tabindex="-1">Connect to WebSocket <a class="header-anchor" href="#connect-to-websocket" aria-label="Permalink to &quot;Connect to WebSocket&quot;">​</a></h5><p><strong>Function:</strong> <code>oa_ws_connect([WebSocketURL])</code></p><p>Connects and authenticates using the API key set with <code>oa_api()</code>. The URL defaults to the saved value (<code>ws://127.0.0.1:8765</code>) and any URL you pass is persisted.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_ws_connect()</span></span>
<span class="line"><span>=oa_ws_connect(&quot;wss://yourdomain.com/ws&quot;)</span></span></code></pre></div><p>Subscriptions are restored automatically after a reconnect.</p><h5 id="disconnect" tabindex="-1">Disconnect <a class="header-anchor" href="#disconnect" aria-label="Permalink to &quot;Disconnect&quot;">​</a></h5><p><strong>Function:</strong> <code>oa_ws_disconnect()</code></p><p>Unsubscribes everything and closes the connection.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_ws_disconnect()</span></span></code></pre></div><h5 id="connection-status" tabindex="-1">Connection Status <a class="header-anchor" href="#connection-status" aria-label="Permalink to &quot;Connection Status&quot;">​</a></h5><table tabindex="0"><thead><tr><th>Function</th><th>Returns</th></tr></thead><tbody><tr><td><code>oa_ws_status()</code></td><td>The current connection state</td></tr><tr><td><code>oa_ws_ping()</code></td><td>Round trip to the server in milliseconds</td></tr><tr><td><code>oa_ws_brokers()</code></td><td>Brokers supported by the connected server</td></tr><tr><td><code>oa_ws_brokerinfo()</code></td><td>Broker and adapter status for the authenticated session</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_ws_status()</span></span>
<span class="line"><span>=oa_ws_ping()</span></span>
<span class="line"><span>=oa_ws_brokers()</span></span>
<span class="line"><span>=oa_ws_brokerinfo()</span></span></code></pre></div><hr><h4 id="streaming-data-functions" tabindex="-1">Streaming Data Functions <a class="header-anchor" href="#streaming-data-functions" aria-label="Permalink to &quot;Streaming Data Functions&quot;">​</a></h4><h5 id="ltp" tabindex="-1">LTP <a class="header-anchor" href="#ltp" aria-label="Permalink to &quot;LTP&quot;">​</a></h5><p><strong>Function:</strong> <code>oa_ws_ltp(Symbol, Exchange)</code></p><p>Streams the last traded price as a single number.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_ws_ltp(&quot;RELIANCE&quot;, &quot;NSE&quot;)</span></span></code></pre></div><h5 id="quote" tabindex="-1">Quote <a class="header-anchor" href="#quote" aria-label="Permalink to &quot;Quote&quot;">​</a></h5><p><strong>Function:</strong> <code>oa_ws_quote(Symbol, Exchange)</code></p><p>Streams the full quote as a two-column key/value table.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_ws_quote(&quot;RELIANCE&quot;, &quot;NSE&quot;)</span></span></code></pre></div><h5 id="depth" tabindex="-1">Depth <a class="header-anchor" href="#depth" aria-label="Permalink to &quot;Depth&quot;">​</a></h5><p><strong>Function:</strong> <code>oa_ws_depth(Symbol, Exchange, [DepthLevel])</code></p><p>Streams the order book as a seven-column table: Bid Orders, Bid Qty, Bid Price, LTP, Ask Price, Ask Qty, Ask Orders.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_ws_depth(&quot;RELIANCE&quot;, &quot;NSE&quot;)</span></span>
<span class="line"><span>=oa_ws_depth(&quot;RELIANCE&quot;, &quot;NSE&quot;, 20)</span></span></code></pre></div><h5 id="single-field" tabindex="-1">Single Field <a class="header-anchor" href="#single-field" aria-label="Permalink to &quot;Single Field&quot;">​</a></h5><p><strong>Function:</strong> <code>oa_ws_field(Symbol, Exchange, Field, [Mode])</code></p><p>Streams one named field as a single value. <code>mode</code> defaults to 2 (Quote).</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_ws_field(&quot;RELIANCE&quot;, &quot;NSE&quot;, &quot;ltp&quot;)</span></span>
<span class="line"><span>=oa_ws_field(&quot;RELIANCE&quot;, &quot;NSE&quot;, &quot;volume&quot;, 2)</span></span></code></pre></div><h5 id="order-updates" tabindex="-1">Order Updates <a class="header-anchor" href="#order-updates" aria-label="Permalink to &quot;Order Updates&quot;">​</a></h5><p><strong>Function:</strong> <code>oa_ws_orders([MaxRows])</code></p><p>Streams real-time order updates for the account as a table, newest first. Buffered up to 200 entries.</p><p><strong>Function:</strong> <code>oa_ws_unsubscribe_orders()</code> stops the stream.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_ws_unsubscribe_orders()</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_ws_orders()</span></span>
<span class="line"><span>=oa_ws_orders(20)</span></span></code></pre></div><hr><h4 id="update-rate" tabindex="-1">Update Rate <a class="header-anchor" href="#update-rate" aria-label="Permalink to &quot;Update Rate&quot;">​</a></h4><p>There are <strong>two independent throttles</strong> between a tick arriving and a cell changing. Both must be open for real-time updates.</p><table tabindex="0"><thead><tr><th>Throttle</th><th>Owned by</th><th>Default</th><th>Set with</th></tr></thead><tbody><tr><td>How often the add-in pushes a topic</td><td>This add-in</td><td>0 (every tick)</td><td><code>oa_ws_throttle()</code></td></tr><tr><td>How often Excel collects pushed values</td><td>Excel</td><td><strong>2000 ms</strong></td><td><code>oa_rtd_interval()</code></td></tr></tbody></table><h5 id="excel-s-rtd-interval" tabindex="-1">Excel&#39;s RTD interval <a class="header-anchor" href="#excel-s-rtd-interval" aria-label="Permalink to &quot;Excel&#39;s RTD interval&quot;">​</a></h5><p><strong>Function:</strong> <code>oa_rtd_interval([Milliseconds])</code></p><p>Excel applies its own limit, <code>Application.RTD.ThrottleInterval</code>, to every RTD server. It ships at <strong>2000 ms</strong>, so a streaming cell repaints only once every two seconds no matter how fast data arrives. Broker feeds run at roughly 1 to 11 updates per second, so Excel&#39;s default discards most of them and live data looks frozen.</p><p>The add-in sets this to 0 on load and again on <code>oa_ws_connect()</code>. Use this function to read or change it.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_rtd_interval()      Read the value Excel is using</span></span>
<span class="line"><span>=oa_rtd_interval(0)     Update as soon as data arrives (default)</span></span>
<span class="line"><span>=oa_rtd_interval(2000)  Excel&#39;s own default</span></span>
<span class="line"><span>=oa_rtd_interval(-1)    Freeze streaming until a manual recalculation</span></span></code></pre></div><p>This is a per-user Excel setting, not a workbook setting, and Excel persists it. <code>oa_version()</code> reports the live value, so a reading of 2000 there explains a sheet that looks stalled.</p><h5 id="the-add-in-s-own-throttle" tabindex="-1">The add-in&#39;s own throttle <a class="header-anchor" href="#the-add-in-s-own-throttle" aria-label="Permalink to &quot;The add-in&#39;s own throttle&quot;">​</a></h5><p><strong>Function:</strong> <code>oa_ws_throttle([Milliseconds])</code></p><p>Sets the minimum gap between two pushed updates for one streaming cell. Omit the argument to read the current value. The setting is persisted.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_ws_throttle()       Read the current value</span></span>
<span class="line"><span>=oa_ws_throttle(0)      Default: push every tick</span></span>
<span class="line"><span>=oa_ws_throttle(250)    At most 4 updates per second per cell</span></span></code></pre></div><p>The throttle is <strong>leading plus trailing edge</strong>. Its guarantee: <em>the last value the server sent for a topic always reaches the cell, at most <code>throttle</code> milliseconds late.</em> A tick held back by the throttle is released by a trailing flush rather than dropped, so the final print of an illiquid strike, or a closing price, never sits stale in the sheet.</p><p>Leave it at 0 for real-time behaviour. Raise it only if a very large sheet on a fast feed starts to feel heavy.</p><hr><h4 id="subscription-management" tabindex="-1">Subscription Management <a class="header-anchor" href="#subscription-management" aria-label="Permalink to &quot;Subscription Management&quot;">​</a></h4><h5 id="subscribe-manually" tabindex="-1">Subscribe Manually <a class="header-anchor" href="#subscribe-manually" aria-label="Permalink to &quot;Subscribe Manually&quot;">​</a></h5><p><strong>Function:</strong> <code>oa_ws_subscribe(Symbol, Exchange, Mode, [DepthLevel])</code></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_ws_subscribe(&quot;RELIANCE&quot;, &quot;NSE&quot;, 1)</span></span>
<span class="line"><span>=oa_ws_subscribe(&quot;RELIANCE&quot;, &quot;NSE&quot;, 3, 20)</span></span></code></pre></div><p>Per-mode shorthands matching the Python SDK&#39;s <code>subscribe_ltp</code>, <code>subscribe_quote</code> and <code>subscribe_depth</code>:</p><table tabindex="0"><thead><tr><th>Function</th><th>Equivalent to</th></tr></thead><tbody><tr><td><code>oa_ws_subscribe_ltp(symbol, exchange)</code></td><td><code>oa_ws_subscribe(..., 1)</code></td></tr><tr><td><code>oa_ws_subscribe_quote(symbol, exchange)</code></td><td><code>oa_ws_subscribe(..., 2)</code></td></tr><tr><td><code>oa_ws_subscribe_depth(symbol, exchange, [depth_level])</code></td><td><code>oa_ws_subscribe(..., 3)</code></td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_ws_subscribe_ltp(&quot;RELIANCE&quot;, &quot;NSE&quot;)</span></span>
<span class="line"><span>=oa_ws_subscribe_quote(&quot;RELIANCE&quot;, &quot;NSE&quot;)</span></span>
<span class="line"><span>=oa_ws_subscribe_depth(&quot;RELIANCE&quot;, &quot;NSE&quot;, 20)</span></span></code></pre></div><h5 id="unsubscribe" tabindex="-1">Unsubscribe <a class="header-anchor" href="#unsubscribe" aria-label="Permalink to &quot;Unsubscribe&quot;">​</a></h5><table tabindex="0"><thead><tr><th>Function</th><th>Purpose</th></tr></thead><tbody><tr><td><code>oa_ws_unsubscribe(symbol, exchange, mode)</code></td><td>One symbol and mode</td></tr><tr><td><code>oa_ws_unsubscribe_ltp(symbol, exchange)</code></td><td>LTP only</td></tr><tr><td><code>oa_ws_unsubscribe_quote(symbol, exchange)</code></td><td>Quote only</td></tr><tr><td><code>oa_ws_unsubscribe_depth(symbol, exchange)</code></td><td>Depth only</td></tr><tr><td><code>oa_ws_unsubscribe_all()</code></td><td>Everything</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_ws_unsubscribe(&quot;RELIANCE&quot;, &quot;NSE&quot;, 1)</span></span>
<span class="line"><span>=oa_ws_unsubscribe_ltp(&quot;RELIANCE&quot;, &quot;NSE&quot;)</span></span>
<span class="line"><span>=oa_ws_unsubscribe_quote(&quot;RELIANCE&quot;, &quot;NSE&quot;)</span></span>
<span class="line"><span>=oa_ws_unsubscribe_depth(&quot;RELIANCE&quot;, &quot;NSE&quot;)</span></span>
<span class="line"><span>=oa_ws_unsubscribe_all()</span></span></code></pre></div><p>After a manual unsubscribe the cell shows <code>Unsubscribed</code> and does <strong>not</strong> auto-resubscribe.</p><h5 id="view-active-subscriptions" tabindex="-1">View Active Subscriptions <a class="header-anchor" href="#view-active-subscriptions" aria-label="Permalink to &quot;View Active Subscriptions&quot;">​</a></h5><p><strong>Function:</strong> <code>oa_ws_subscriptions()</code></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_ws_subscriptions()</span></span></code></pre></div><h5 id="debug" tabindex="-1">Debug <a class="header-anchor" href="#debug" aria-label="Permalink to &quot;Debug&quot;">​</a></h5><p><strong>Function:</strong> <code>oa_ws_debug(Symbol, Exchange, Mode)</code></p><p>Shows subscription status and cached data keys.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=oa_ws_debug(&quot;RELIANCE&quot;, &quot;NSE&quot;, 1)</span></span></code></pre></div><hr><h4 id="websocket-data-modes" tabindex="-1">WebSocket Data Modes <a class="header-anchor" href="#websocket-data-modes" aria-label="Permalink to &quot;WebSocket Data Modes&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Mode</th><th>Name</th><th>Contents</th></tr></thead><tbody><tr><td>1</td><td>LTP</td><td>Last traded price only, lightest</td></tr><tr><td>2</td><td>Quote</td><td>OHLC, volume, LTP, change</td></tr><tr><td>3</td><td>Depth</td><td>Full order book, 5 to 50 levels by broker</td></tr></tbody></table><hr><h4 id="websocket-quick-start-example" tabindex="-1">WebSocket Quick Start Example <a class="header-anchor" href="#websocket-quick-start-example" aria-label="Permalink to &quot;WebSocket Quick Start Example&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>A1: =oa_api(&quot;your_api_key&quot;)</span></span>
<span class="line"><span>A2: =oa_ws_connect()</span></span>
<span class="line"><span>A3: =oa_ws_status()</span></span>
<span class="line"><span></span></span>
<span class="line"><span>A5: =oa_ws_ltp(&quot;RELIANCE&quot;, &quot;NSE&quot;)</span></span>
<span class="line"><span>A6: =oa_ws_ltp(&quot;TCS&quot;, &quot;NSE&quot;)</span></span>
<span class="line"><span>A7: =oa_ws_ltp(&quot;INFY&quot;, &quot;NSE&quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>A9: =oa_ws_depth(&quot;RELIANCE&quot;, &quot;NSE&quot;)</span></span></code></pre></div><hr><h3 id="debugging-and-logs" tabindex="-1">Debugging and Logs <a class="header-anchor" href="#debugging-and-logs" aria-label="Permalink to &quot;Debugging and Logs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Location</th><th>Contents</th></tr></thead><tbody><tr><td><code>%LOCALAPPDATA%\\Tradeboard\\websocket.log</code></td><td>WebSocket connection and subscription log</td></tr><tr><td><code>%LOCALAPPDATA%\\Tradeboard\\config.json</code></td><td>Saved API key, host URL, and settings</td></tr></tbody></table><p>Start any troubleshooting with <code>=oa_version()</code> and <code>=oa_ping()</code>.</p><hr><h3 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h3><ul><li>All functions require <code>oa_api()</code> to be configured first. The key is persisted, so this is normally a one-time step.</li><li>Order functions send as soon as they are called. <code>oa_trading_enabled(FALSE)</code> is an optional guard against a recalculation re-placing an order.</li><li>Streaming functions (<code>oa_ws_ltp</code>, <code>oa_ws_quote</code>, <code>oa_ws_depth</code>, <code>oa_ws_field</code>, <code>oa_ws_orders</code>) update by RTD push. They are <strong>not</strong> volatile and do not trigger workbook recalculation.</li><li>If streaming looks frozen, check <code>oa_rtd_interval()</code>. Excel caps RTD collection at 2000 ms by default; the add-in lowers it to 0, but a policy or another add-in can raise it again.</li><li><strong>REST functions cache their result.</strong> Excel-DNA keys the async result on the function name plus its arguments, so a function such as <code>oa_funds()</code> fetches once and keeps returning the same value. Press <strong>Ctrl+Alt+F9</strong> to force a full rebuild and refetch, or edit the formula.</li><li>Cells show <code>#N/A</code> while a request is in flight.</li><li>Order IDs and instrument tokens are returned as <strong>text</strong>, so they keep their exact digits. Reference them directly rather than retyping.</li><li>Timestamps are converted to IST. <code>oa_history</code> returns a real Excel date serial that charts directly.</li><li>Functions are grouped in the Excel function wizard under categories beginning with <code>Tradeboard</code>.</li><li>The add-in ships IntelliSense, so argument names and descriptions appear as you type.</li></ul><hr><h3 id="function-index" tabindex="-1">Function Index <a class="header-anchor" href="#function-index" aria-label="Permalink to &quot;Function Index&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Category</th><th>Functions</th></tr></thead><tbody><tr><td>Configuration</td><td><code>oa_api</code>, <code>oa_version</code>, <code>oa_ping</code>, <code>oa_trading_enabled</code>, <code>oa_request</code>, <code>oa_json</code></td></tr><tr><td>Account</td><td><code>oa_funds</code>, <code>oa_orderbook</code>, <code>oa_orderbook_stats</code>, <code>oa_tradebook</code>, <code>oa_positionbook</code>, <code>oa_holdings</code>, <code>oa_holdings_stats</code>, <code>oa_margin</code></td></tr><tr><td>Market Data</td><td><code>oa_ltp</code>, <code>oa_field</code>, <code>oa_quotes</code>, <code>oa_multiquotes</code>, <code>oa_depth</code>, <code>oa_history</code>, <code>oa_intervals</code></td></tr><tr><td>Symbols</td><td><code>oa_symbol</code>, <code>oa_search</code>, <code>oa_expiry</code>, <code>oa_lotsize</code>, <code>oa_token</code></td></tr><tr><td>Options</td><td><code>oa_optionchain</code>, <code>oa_optiongreeks</code>, <code>oa_multioptiongreeks</code>, <code>oa_optionsymbol</code>, <code>oa_syntheticfuture</code>, <code>oa_optionsorder</code>, <code>oa_optionsmultiorder</code></td></tr><tr><td>Orders</td><td><code>oa_placeorder</code>, <code>oa_placesmartorder</code>, <code>oa_basketorder</code>, <code>oa_splitorder</code>, <code>oa_modifyorder</code>, <code>oa_cancelorder</code>, <code>oa_cancelallorder</code>, <code>oa_closeposition</code>, <code>oa_orderstatus</code>, <code>oa_openposition</code></td></tr><tr><td>GTT</td><td><code>oa_placegttorder</code>, <code>oa_modifygttorder</code>, <code>oa_cancelgttorder</code>, <code>oa_gttorderbook</code></td></tr><tr><td>Analyzer</td><td><code>oa_analyzerstatus</code>, <code>oa_analyzertoggle</code>, <code>oa_pnl_symbols</code></td></tr><tr><td>Calendar</td><td><code>oa_holidays</code>, <code>oa_timings</code>, <code>oa_isholiday</code></td></tr><tr><td>Chart</td><td><code>oa_chart</code>, <code>oa_chart_set</code></td></tr><tr><td>Messaging</td><td><code>oa_whatsapp</code>, <code>oa_telegram</code></td></tr><tr><td>WebSocket</td><td><code>oa_ws_connect</code>, <code>oa_ws_disconnect</code>, <code>oa_ws_status</code>, <code>oa_ws_ping</code>, <code>oa_ws_brokers</code>, <code>oa_ws_brokerinfo</code>, <code>oa_ws_ltp</code>, <code>oa_ws_quote</code>, <code>oa_ws_depth</code>, <code>oa_ws_field</code>, <code>oa_ws_orders</code>, <code>oa_ws_throttle</code>, <code>oa_rtd_interval</code>, <code>oa_ws_subscribe</code>, <code>oa_ws_subscribe_ltp</code>, <code>oa_ws_subscribe_quote</code>, <code>oa_ws_subscribe_depth</code>, <code>oa_ws_unsubscribe</code>, <code>oa_ws_unsubscribe_ltp</code>, <code>oa_ws_unsubscribe_quote</code>, <code>oa_ws_unsubscribe_depth</code>, <code>oa_ws_unsubscribe_orders</code>, <code>oa_ws_unsubscribe_all</code>, <code>oa_ws_subscriptions</code>, <code>oa_ws_debug</code></td></tr></tbody></table><hr><h3 id="support-and-contributions" tabindex="-1">Support and Contributions <a class="header-anchor" href="#support-and-contributions" aria-label="Permalink to &quot;Support and Contributions&quot;">​</a></h3><ul><li><strong>Issues</strong>: Report issues at the <a href="https://github.com/marketcalls/Tradeboard-Excel/issues" target="_blank" rel="noreferrer">repository&#39;s issue tracker</a>.</li><li><strong>Contributions</strong>: PRs are welcome to improve features, documentation, or bug fixes.</li><li><strong>License</strong>: Tradeboard is open-source and distributed under the <strong>AGPL-3.0 License</strong>.</li></ul><h3 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h3><ul><li><a href="https://docs.algo.wesoftcorp.com/api-documentation/v1/" target="_blank" rel="noreferrer">Tradeboard API Docs</a></li><li><a href="https://github.com/marketcalls/Tradeboard-Excel" target="_blank" rel="noreferrer">Tradeboard Excel Add-In on GitHub</a></li><li><a href="https://excel-dna.net/" target="_blank" rel="noreferrer">Excel-DNA Documentation</a></li><li><a href="https://dotnet.microsoft.com/en-us/download/dotnet/8.0" target="_blank" rel="noreferrer">Download .NET 8 Desktop Runtime</a></li></ul><h3 id="disclaimer" tabindex="-1">Disclaimer <a class="header-anchor" href="#disclaimer" aria-label="Permalink to &quot;Disclaimer&quot;">​</a></h3><p>The creators of this add-in are not responsible for any issues, losses, or damages that may arise from its use. It is strongly recommended to test all functionalities in Tradeboard Analyzer Mode before applying them to live trading. Always verify API responses and exercise caution while executing trades.</p>`,437)])])}const g=t(n,[["render",d]]);export{h as __pageData,g as default};
